items.signature:
FMOD_Studio_Parameter_ID : struct
{
    data1 : u32
    data2 : u32
}

FMOD_Studio_User_Property : struct
{
    name  : cstring
    type  : FMOD_Studio_User_Property_Type
    value : FMOD_Studio_User_Property_Value
}

FMOD_Vector : struct
{
    x : f32
    y : f32
    z : f32
}

FMOD_Studio_Buffer_Usage : struct
{
    studiocommandqueue : FMOD_Studio_Buffer_Info
    studiohandle       : FMOD_Studio_Buffer_Info
}

FMOD_Studio_Programmer_Sound_Properties : struct
{
    name          : cstring
    sound         : ^FMOD_Sound
    subsoundIndex : i32
}

FMOD_Studio_Timeline_Marker_Properties : struct
{
    name     : cstring
    position : i32
}

FMOD_Studio_Memory_Usage : struct
{
    exclusive  : i32
    inclusive  : i32
    sampledata : i32
}

Vector3 : struct {

    x, y, z : f32 = 0.0
}

Vector4 : struct {

    x, y, z, w : f32 = 0.0
}

Color : struct {

    R : u8 = 255
    G : u8 = 255
    B : u8 = 255
    A : u8 = 255

}

Rectangle : struct {

    x       : f32        // Rectangle top-left corner position x
    y       : f32        // Rectangle top-left corner position y
    width   : f32        // Rectangle width
    height  : f32        // Rectangle height

}

RenderTexture : struct {

    id : u32             // OpenGL framebuffer object id
    texture : Texture    // Color buffer attachment texture
    depth : Texture      // Depth buffer attachment texture

}

Camera2D : struct {

    offset    : Vector2
    target    : Vector2
    rotation  : f32
    zoom      : f32

}

stbtt__hheap : struct {
    head : ^stbtt__hheap_chunk
    first_free : ^void
    num_remaining_in_head_chunk : i32
}

stbtt__buf : struct {
    data : ^u8
    cursor : i32
    size : i32
}

stbtt__bitmap : struct {
    w : i32
    h : i32
    stride : i32
    pixels : ^u8
}

stbtt__point : struct {
    x : f32
    y : f32
}

stbtt_kerningentry : struct {
    glyph1 : i32
    glyph2 : i32
    advance : i32
}
